"""Compile one Zig module to an object file for the meson build.

Meson calls this for every `*.zig` module. It mirrors the C build's
configuration:

* the optimize mode follows meson's `--buildtype` when `zig_optimize=auto`
  (debug -> Debug, release -> ReleaseSafe, minsize -> ReleaseSmall)
* a non-auto `zig_optimize` (or an explicit `--optimize=MODE`) overrides that
  mapping, e.g. for a fair C-vs-Zig ReleaseFast benchmark
* `build_options` mirrors meson feature options (grapheme clustering)
* `c_layout` (generated by `abi_probe.c`) is imported by
  `terminal_types.zig` to check the ABI mirror at compile time

Usage: compile_zig.py [--optimize=MODE] INPUT.zig OUTPUT.o
                                [grapheme_clustering: true|false]
                                [name=value ...]

MODE is one of Debug, ReleaseSafe, ReleaseFast, ReleaseSmall. The option may
appear anywhere in the argument list and is optional; the existing
`INPUT.zig OUTPUT.o [flags]` invocation is unchanged.

Extra `name=value` arguments are written to the generated `build_options`
module as `pub const name = value;`, so a module can mirror any meson
feature flag it needs.
"""

import json
import os
import subprocess
import sys

# The migration branch is developed against this Zig series.
ZIG_SERIES = "0.16"

OPTIMIZE_MODES = {
    "debug": "Debug",
    "debugoptimized": "ReleaseSafe",
    "release": "ReleaseSafe",
    "minsize": "ReleaseSmall",
}

# `auto` keeps the buildtype mapping above; the other values are Zig's
# optimization modes and are also the meson `zig_optimize` combo choices.
OPTIMIZE_CHOICES = (
    "auto", "Debug", "ReleaseSafe", "ReleaseFast", "ReleaseSmall",
)
ZIG_OPTIMIZE_MODES = OPTIMIZE_CHOICES[1:]


def zig_version():
    try:
        out = subprocess.run(
            ["zig", "version"], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError):
        sys.exit("compile_zig.py: could not run `zig version`; is Zig installed?")
    return out.stdout.strip()


def check_version(version):
    if not version.startswith(ZIG_SERIES + "."):
        sys.exit(
            f"compile_zig.py: Zig {ZIG_SERIES} is required (found {version})")


def meson_build_option(name, build_dir=None):
    """Read a meson build option from meson-info/intro-buildoptions.json.

    Meson does not export MESON_BUILD_ROOT to custom_target commands, so
    fall back to the directory passed by the caller - every Zig object is
    emitted inside the build dir, next to meson-info/.
    """
    root = os.environ.get("MESON_BUILD_ROOT") or build_dir
    if not root:
        return None
    path = os.path.join(root, "meson-info", "intro-buildoptions.json")
    try:
        with open(path, "r", encoding="utf-8") as f:
            options = json.load(f)
    except (OSError, ValueError):
        return None
    for option in options:
        if option.get("name") == name:
            return option.get("value")
    return None


def meson_buildtype(build_dir=None):
    """Read meson's buildtype (kept as a convenience wrapper)."""
    return meson_build_option("buildtype", build_dir)


def optimize_mode(build_dir=None, requested=None):
    """Resolve the Zig optimization mode for a build dir.

    `auto` (the meson default) preserves the historical buildtype mapping
    exactly. Any other value must be an explicit Zig mode and wins over the
    buildtype; `requested` is the optional `--optimize` CLI override.
    """
    if requested is None:
        requested = meson_build_option("zig_optimize", build_dir) or "auto"
    if requested == "auto":
        return OPTIMIZE_MODES.get(meson_buildtype(build_dir) or "", "ReleaseSafe")
    if requested not in ZIG_OPTIMIZE_MODES:
        sys.exit(
            "compile_zig.py: invalid optimize mode %r (expected one of %s)"
            % (requested, ", ".join(OPTIMIZE_CHOICES)))
    return requested


def version_from_header(path):
    """Return FOOT_VERSION's literal (including quotes) from generate-version.sh's header."""
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.startswith("#define FOOT_VERSION "):
                return line[len("#define FOOT_VERSION "):].strip()
    sys.exit(f"compile_zig.py: no FOOT_VERSION in {path}")


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(__doc__)
        return

    # Extract the optional override without disturbing the meson custom
    # targets' `INPUT OUTPUT [flags]` positional convention.
    optimize_override = None
    positional = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith("--optimize="):
            optimize_override = arg.split("=", 1)[1]
        elif arg == "--optimize":
            i += 1
            if i == len(args):
                sys.exit("compile_zig.py: --optimize requires a value")
            optimize_override = args[i]
        else:
            positional.append(arg)
        i += 1

    if len(positional) < 2:
        sys.exit(__doc__)

    input_file, output_file = positional[:2]
    grapheme_clustering = None
    extra_options: dict[str, str] = {}
    for arg in positional[2:]:
        if "=" in arg:
            name, value = arg.split("=", 1)
            # `version=<path to version.h>`: the version string is generated
            # by generate-version.sh at build time, so read it from the header
            # and re-emit FOOT_VERSION's literal verbatim (C and Zig string
            # literal escapes happen to agree).
            if name == "version":
                extra_options["foot_version"] = version_from_header(value)
                continue
            # A value is either a bool or a Zig string literal ("...").
            # The latter mirrors C string #defines (e.g. a path).
            is_string = len(value) >= 2 and value[0] == '"' and value[-1] == '"'
            if value not in ("true", "false") and not is_string:
                sys.exit(
                    f"compile_zig.py: {name}: expected true/false or a "
                    f'quoted string, got {value!r}')
            extra_options[name] = value
        elif arg in ("true", "false"):
            grapheme_clustering = arg
        else:
            sys.exit(f"compile_zig.py: unexpected argument {arg!r}")

    check_version(zig_version())

    out_dir = os.path.dirname(os.path.abspath(output_file))
    optimize = optimize_mode(out_dir, optimize_override)

    cmd = ["zig", "build-obj", "-O", optimize, "-fno-stack-check", "-lc"]

    # Meson generates build_options next to the output, and c_layout.zig
    # likewise (unless the target predates the ABI probe).
    opts_file = None
    if grapheme_clustering is not None or extra_options:
        opts_file = output_file + ".build_options.zig"
        with open(opts_file, "w", encoding="utf-8") as f:
            if grapheme_clustering is not None:
                f.write(
                    "pub const grapheme_clustering = %s;\n"
                    % ("true" if grapheme_clustering == "true" else "false"))
            for name, value in extra_options.items():
                f.write(f"pub const {name} = {value};\n")

    layout_file = os.path.join(out_dir, "c_layout.zig")
    if not os.path.exists(layout_file):
        layout_file = None

    deps = []
    if opts_file is not None:
        deps.append(("build_options", opts_file))
    if layout_file is not None:
        deps.append(("c_layout", layout_file))

    for name, path in deps:
        cmd += ["--dep", name]
    cmd += ["-Mroot=" + input_file]
    for name, path in deps:
        cmd += [f"-M{name}={path}"]

    cmd += ["-femit-bin=" + output_file]

    subprocess.run(cmd, check=True)


if __name__ == "__main__":
    main()
